    "contracts/Convertible.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity =0.8.19;

/**************************************************************************************************************************************************

 /$$$$$$$$                                 /$$$$$$$$ /$$                                                  
| $$_____/                                | $$_____/|__/                                                  
| $$    /$$$$$$  /$$$$$$$   /$$$$$$       | $$       /$$ /$$$$$$$   /$$$$$$  /$$$$$$$   /$$$$$$$  /$$$$$$ 
| $$$$$|____  $$| $$__  $$ /$$__  $$      | $$$$$   | $$| $$__  $$ |____  $$| $$__  $$ /$$_____/ /$$__  $$
| $$__/ /$$$$$$$| $$  \ $$| $$  \ $$      | $$__/   | $$| $$  \ $$  /$$$$$$$| $$  \ $$| $$      | $$$$$$$$
| $$   /$$__  $$| $$  | $$| $$  | $$      | $$      | $$| $$  | $$ /$$__  $$| $$  | $$| $$      | $$_____/
| $$  |  $$$$$$$| $$  | $$|  $$$$$$$      | $$      | $$| $$  | $$|  $$$$$$$| $$  | $$|  $$$$$$$|  $$$$$$$
|__/   \_______/|__/  |__/ \____  $$      |__/      |__/|__/  |__/ \_______/|__/  |__/ \_______/ \_______/
                           /$$  \ $$                                                                      
                          |  $$$$$$/                                                                      
                           \______/                                                                       
                                                                                                                                                    
#### Website: https://fang.finance/
#### Author: kell (adaptions)

// @title FANG Convertible: launch-price conversion of genesis principal into pre-funded FANG
// @notice Only GenesisFarm may convert, during CONVERT_WINDOW after poolEndTime, which the farm gates.
//         Prices and per-token caps are posted by the owner, prices in USD; the conversion is capped to
//         the contract balance and the token's cap, with a per-user cap that doubles every CAP_DOUBLING_PERIOD.
// @dev    Not a fork. OpenZeppelin Ownable, ReentrancyGuard and SafeERC20.
// Built for Robinhood Chain

**************************************************************************************************************************************************/

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IERC20Decimals {
    function decimals() external view returns (uint8);
}

interface IGmcdToken is IERC20 {
    function burn(uint256 _amount) external;
}

interface IGenesisFarm {
    function poolEndTime() external view returns (uint256);
    function CONVERT_WINDOW() external view returns (uint256);
}

contract Convertible is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant CAP_DOUBLING_PERIOD = 30 minutes;

    address public immutable gmcd;
    address public immutable genesisFarm;
    uint256 public immutable initialMaxMcdOutPerUser;
    address public treasury;
    uint256 public mcdPriceUsd = 1e18;
    mapping(address => uint256) public tokenPriceUsd;
    mapping(address => uint256) public userMcdOut;
    mapping(address => uint256) public tokenMaxMcdOut;
    mapping(address => uint256) public tokenMcdOut;
    uint256 public totalConverted;

    event Converted(address indexed user, address indexed token, uint256 amount, uint256 gmcdOut);
    event McdPriceUsdUpdated(uint256 price);
    event TokenPriceUsdUpdated(address indexed token, uint256 price);
    event TokenMaxMcdOutUpdated(address indexed token, uint256 maxMcdOut);
    event TreasuryUpdated(address indexed treasury);
    event GmcdWithdrawn(address indexed to, uint256 amount);
    event GmcdBurned(uint256 amount);

    modifier onlyFarm() {
        require(msg.sender == genesisFarm, "Convertible: caller is not the farm");
        _;
    }

    constructor(
        address _gmcd,
        address _genesisFarm,
        address _treasury,
        uint256 _initialMaxMcdOutPerUser,
        address _owner
    ) {
        require(_gmcd != address(0), "Convertible: gmcd is zero");
        require(_genesisFarm != address(0), "Convertible: farm is zero");
        require(_treasury != address(0), "Convertible: treasury is zero");
        require(
            _initialMaxMcdOutPerUser > 0 && _initialMaxMcdOutPerUser <= type(uint128).max,
            "Convertible: initial cap out of range"
        );
        require(_owner != address(0), "Convertible: owner is zero");
        _transferOwnership(_owner);
        gmcd = _gmcd;
        genesisFarm = _genesisFarm;
        treasury = _treasury;
        initialMaxMcdOutPerUser = _initialMaxMcdOutPerUser;
    }

    /// @notice gMCD `_amount` of `_token` converts into, applying decimal scaling.
    function quote(address _token, uint256 _amount) public view returns (uint256 gmcdOut) {
        uint256 mcdPrice = mcdPriceUsd;
        require(mcdPrice > 0, "Convertible: MCD price not set");
        uint256 tokenPrice = tokenPriceUsd[_token];
        require(tokenPrice > 0, "Convertible: token price not set");
        uint256 scale = _scale(IERC20Decimals(_token).decimals());
        require(scale > 0, "Convertible: unsupported decimals");
        gmcdOut = _amount * scale * tokenPrice / mcdPrice;
    }

    function _scale(uint8 _decimals) internal pure returns (uint256) {
        return _decimals <= 18 ? 10 ** (18 - _decimals) : 0;
    }

    /// @notice gMCD this contract still holds to convert.
    function remainingMcdOut() public view returns (uint256) {
        return IGmcdToken(gmcd).balanceOf(address(this));
    }

    /// @notice Per-user cap on gMCD out: the initial cap, doubled every CAP_DOUBLING_PERIOD since the window opened; no cap once closed.
    function maxMcdOutPerUser() public view returns (uint256) {
        (uint256 start, uint256 end) = convertWindow();
        if (block.timestamp <= start) return initialMaxMcdOutPerUser;
        if (block.timestamp >= end) return type(uint256).max;
        return initialMaxMcdOutPerUser * 2 ** ((block.timestamp - start) / CAP_DOUBLING_PERIOD);
    }

    /// @notice gMCD still available to `_user`: the smaller of the per-user remainder and the balance.
    function remainingMcdOutFor(address _user) public view returns (uint256) {
        uint256 cap = maxMcdOutPerUser();
        uint256 userRemaining = cap > userMcdOut[_user] ? cap - userMcdOut[_user] : 0;
        uint256 remaining = remainingMcdOut();
        return userRemaining < remaining ? userRemaining : remaining;
    }

    /// @notice gMCD still payable against `_token`: the smaller of the token's cap remainder and the balance.
    function remainingMcdOutForToken(address _token) public view returns (uint256) {
        uint256 cap = tokenMaxMcdOut[_token];
        uint256 tokenRemaining = cap > tokenMcdOut[_token] ? cap - tokenMcdOut[_token] : 0;
        uint256 remaining = remainingMcdOut();
        return tokenRemaining < remaining ? tokenRemaining : remaining;
    }

    /// @notice Largest `_token` amount `_user` can convert without exceeding a cap; 0 when closed, unpriced or the token's cap is spent.
    function maxTokenIn(address _token, address _user) external view returns (uint256) {
        uint256 tokenPrice = tokenPriceUsd[_token];
        if (!isOpen() || tokenPrice == 0 || mcdPriceUsd == 0) return 0;
        uint256 scale = _scale(IERC20Decimals(_token).decimals());
        if (scale == 0) return 0;
        uint256 userRemaining = remainingMcdOutFor(_user);
        uint256 tokenRemaining = remainingMcdOutForToken(_token);
        uint256 room = userRemaining < tokenRemaining ? userRemaining : tokenRemaining;
        return room * mcdPriceUsd / tokenPrice / scale;
    }

    /// @notice The conversion window read from GenesisFarm: poolEndTime to poolEndTime + CONVERT_WINDOW.
    function convertWindow() public view returns (uint256 start, uint256 end) {
        start = IGenesisFarm(genesisFarm).poolEndTime();
        end = start + IGenesisFarm(genesisFarm).CONVERT_WINDOW();
    }

    /// @notice True while the farm conversion window is open and gMCD remains to convert.
    function isOpen() public view returns (bool) {
        (uint256 start, uint256 end) = convertWindow();
        return start <= block.timestamp && block.timestamp < end && remainingMcdOut() > 0;
    }

    /// @notice Sets the USD price of MCD, 1e18 fixed point.
    function setMcdPriceUsd(uint256 _price) external onlyOwner {
        mcdPriceUsd = _price;
        emit McdPriceUsdUpdated(_price);
    }

    /// @notice Sets the USD price of one deposit token, 1e18 fixed point per whole token.
    function setTokenPriceUsd(address _token, uint256 _price) public onlyOwner {
        require(_token != address(0), "Convertible: token is zero");
        tokenPriceUsd[_token] = _price;
        emit TokenPriceUsdUpdated(_token, _price);
    }

    /// @notice Sets the USD price of several deposit tokens in one call.
    function setTokenPricesUsd(address[] calldata _tokens, uint256[] calldata _prices) external onlyOwner {
        require(_tokens.length == _prices.length, "Convertible: length mismatch");
        for (uint256 i; i < _tokens.length; ++i) {
            setTokenPriceUsd(_tokens[i], _prices[i]);
        }
    }

    /// @notice Sets the gMCD cap paid out against each deposit token; type(uint256).max means no cap.
    function setTokenMaxMcdOuts(address[] calldata _tokens, uint256[] calldata _maxMcdOuts) external onlyOwner {
        require(_tokens.length == _maxMcdOuts.length, "Convertible: length mismatch");
        for (uint256 i; i < _tokens.length; ++i) {
            require(_tokens[i] != address(0), "Convertible: token is zero");
            tokenMaxMcdOut[_tokens[i]] = _maxMcdOuts[i];
            emit TokenMaxMcdOutUpdated(_tokens[i], _maxMcdOuts[i]);
        }
    }

    /// @notice Sets the address receiving converted principal.
    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "Convertible: treasury is zero");
        treasury = _treasury;
        emit TreasuryUpdated(_treasury);
    }

    /// @notice Sends gMCD out of this contract, lowering what is left to convert.
    function withdrawGmcd(address _to, uint256 _amount) external onlyOwner {
        require(_to != address(0), "Convertible: to is zero");
        emit GmcdWithdrawn(_to, _amount);
        IERC20(gmcd).safeTransfer(_to, _amount);
    }

    /// @notice Converts all of `_amount` of `_token` held by the farm into gMCD for `_user`, or reverts.
    function convert(
        address _token,
        uint256 _amount,
        address _user
    ) external onlyFarm nonReentrant returns (uint256 gmcdOut) {
        gmcdOut = quote(_token, _amount);
        require(gmcdOut > 0, "Convertible: nothing converted");
        require(gmcdOut <= remainingMcdOutFor(_user), "Convertible: cap reached");
        require(gmcdOut <= remainingMcdOutForToken(_token), "Convertible: token cap reached");

        userMcdOut[_user] += gmcdOut;
        tokenMcdOut[_token] += gmcdOut;
        totalConverted += gmcdOut;
        emit Converted(_user, _token, _amount, gmcdOut);

        IERC20(_token).safeTransferFrom(msg.sender, treasury, _amount);
        IERC20(gmcd).safeTransfer(_user, gmcdOut);
    }

    /// @notice Burns the gMCD still held here once the conversion window has closed.
    function burnConverted() external nonReentrant onlyOwner {
        (, uint256 end) = convertWindow();
        require(block.timestamp >= end, "Convertible: window still open");
        uint256 amount = remainingMcdOut();
        require(amount > 0, "Convertible: nothing to burn");
        emit GmcdBurned(amount);
        IGmcdToken(gmcd).burn(amount);
    }
}
"
    },
    "contracts/distribution/GenesisFarm.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity =0.8.19;

/**************************************************************************************************************************************************

 /$$$$$$$$                                 /$$$$$$$$ /$$                                                  
| $$_____/                                | $$_____/|__/                                                  
| $$    /$$$$$$  /$$$$$$$   /$$$$$$       | $$       /$$ /$$$$$$$   /$$$$$$  /$$$$$$$   /$$$$$$$  /$$$$$$ 
| $$$$$|____  $$| $$__  $$ /$$__  $$      | $$$$$   | $$| $$__  $$ |____  $$| $$__  $$ /$$_____/ /$$__  $$
| $$__/ /$$$$$$$| $$  \ $$| $$  \ $$      | $$__/   | $$| $$  \ $$  /$$$$$$$| $$  \ $$| $$      | $$$$$$$$
| $$   /$$__  $$| $$  | $$| $$  | $$      | $$      | $$| $$  | $$ /$$__  $$| $$  | $$| $$      | $$_____/
| $$  |  $$$$$$$| $$  | $$|  $$$$$$$      | $$      | $$| $$  | $$|  $$$$$$$| $$  | $$|  $$$$$$$|  $$$$$$$
|__/   \_______/|__/  |__/ \____  $$      |__/      |__/|__/  |__/ \_______/|__/  |__/ \_______/ \_______/
                           /$$  \ $$                                                                      
                          |  $$$$$$/                                                                      
                           \______/                                                                       
                                                                                                                                                    
#### Website: https://fang.finance/
#### Author: kell (adaptions)

// @title Fang Finance Genesis: Modified from TombGenesisRewardPool (originally from SushiSwap MasterChef)
// @notice Genesis farm: stake listed assets for a fixed xGFANG budget over [poolStartTime, poolEndTime],
//         optionally convert staked principal into xGFANG at the launch price after farming period ends
// @dev    Modifications:
// Modern Solidity
// OpenZeppelin Ownable (instead of Tomb operator) and ReentrancyGuard
// Per-pool deposit fee (forked from SpiritSwap MasterChef's depositFeeBP block)
// Owner may reschedule genesis before it starts, preserving duration and reward budget
// After farming period ends: no more deposits. Farm is whitelist for launch
// Optional conversion of principal via Convertible.sol (capped launch, up to 24h, fcfs)
// Built for Robinhood Chain

**************************************************************************************************************************************************/

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IConvertible {
    function convert(address _token, uint256 _amount, address _user) external returns (uint256 xgfangOut);
}

contract GenesisFarm is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ************************************************************************************************
    // FORK: tomb.finance TombGenesisRewardPool, with SpiritSwap MasterChef's depositFeeBP block
    //
    // Upstream code, Tomb's order. Only lines marked MODIFIED (Tomb: ...) or MODIFIED (SpiritSwap: ...)
    // differ from upstream, beyond the mechanical changes the file header lists.
    // ************************************************************************************************

    // Info of each user.
    struct UserInfo {
        uint256 amount; // How many tokens the user has provided.
        uint256 rewardDebt; // Reward debt. See explanation below.
    }

    // Info of each pool.
    struct PoolInfo {
        IERC20 token; // Address of LP token contract.
        uint256 allocPoint; // How many allocation points assigned to this pool. xGFANG to distribute.
        uint256 lastRewardTime; // Last time that xGFANG distribution occurs.
        uint256 accRewardPerShare; // Accumulated xGFANG per share, times 1e18. See below.
        bool isStarted; // if lastRewardBlock has passed
        uint16 depositFeeBP; // Deposit fee in basis points // MODIFIED (SpiritSwap: the field)
    }

    IERC20 public immutable rewardToken; // MODIFIED (Tomb: IERC20 public tomb)

    // Info of each pool.
    PoolInfo[] public poolInfo;

    // Info of each user that stakes LP tokens.
    mapping(uint256 => mapping(address => UserInfo)) public userInfo;

    // Total allocation points. Must be the sum of all allocation points in all pools.
    uint256 public totalAllocPoint = 0;

    // The time when xGFANG mining starts.
    uint256 public poolStartTime; // MODIFIED (owner may reschedule before genesis starts)

    // The time when xGFANG mining ends.
    uint256 public poolEndTime; // Always poolStartTime + runningTime

    // MODIFIED (set in constructor instead of constants)
    uint256 public immutable runningTime;
    uint256 public immutable totalRewards;
    uint256 public immutable rewardPerSecond;

    event Deposit(address indexed user, uint256 indexed pid, uint256 amount);
    event Withdraw(address indexed user, uint256 indexed pid, uint256 amount);
    event EmergencyWithdraw(address indexed user, uint256 indexed pid, uint256 amount);
    event RewardPaid(address indexed user, uint256 amount);
    event PoolStartTimeUpdated(uint256 previousStartTime, uint256 newStartTime, uint256 newEndTime);

    constructor(
        address _rewardToken,
        uint256 _poolStartTime,
        address _owner,
        uint256 _runningTime,
        uint256 _totalRewards
    ) {
        require(block.timestamp < _poolStartTime, "GenesisFarm: late");
        require(_rewardToken != address(0), "GenesisFarm: zero address");
        rewardToken = IERC20(_rewardToken);
        poolStartTime = _poolStartTime;
        require(_runningTime > 0, "GenesisFarm: zero runningTime");
        runningTime = _runningTime;
        poolEndTime = _poolStartTime + runningTime;
        totalRewards = _totalRewards;
        rewardPerSecond = totalRewards / runningTime; // rounds down: the farm ends with dust, never short
        require(_owner != address(0), "GenesisFarm: owner is zero"); // MODIFIED (Tomb: the deployer is the operator)
        _transferOwnership(_owner); // MODIFIED (Tomb: operator = msg.sender)
    }

    function poolLength() external view returns (uint256) {
        return poolInfo.length;
    }

    /// @notice Moves genesis earlier or later, provided the current and new start times are still in the future.
    /// @dev Preserves the duration, emission rate, allocations and deposits. No rewards have accrued yet.
    function setPoolStartTime(uint256 _poolStartTime) external onlyOwner {
        require(block.timestamp < poolStartTime, "GenesisFarm: already started");
        require(block.timestamp < _poolStartTime, "GenesisFarm: start must be in future");

        uint256 previousStartTime = poolStartTime;
        poolStartTime = _poolStartTime;
        poolEndTime = _poolStartTime + runningTime;

        // MODIFIED (all pools added before genesis start together; add disallows delayed starts).
        uint256 length = poolInfo.length;
        for (uint256 pid = 0; pid < length; ++pid) {
            poolInfo[pid].lastRewardTime = _poolStartTime;
        }

        emit PoolStartTimeUpdated(previousStartTime, _poolStartTime, poolEndTime);
    }

    function _checkPoolDuplicate(IERC20 _token) internal view {
        uint256 length = poolInfo.length;
        for (uint256 pid = 0; pid < length; ++pid) {
            require(poolInfo[pid].token != _token, "GenesisFarm: existing pool?");
        }
    }

    // Add a new token to the pool. Can only be called by the owner.
    function add(
        uint256 _allocPoint,
        IERC20 _token,
        uint16 _depositFeeBP,
        bool _withUpdate,
        uint256 _lastRewardTime
    ) public onlyOwner {
        _checkPoolDuplicate(_token);
        require(_token != rewardToken, "GenesisFarm: reward token"); // MODIFIED (Tomb: no such check)
        require(_depositFeeBP <= 500, "GenesisFarm: add: invalid deposit fee basis points");
        require(_lastRewardTime == 0, "GenesisFarm: add: delayed start"); // MODIFIED (Tomb: no such check)
        if (_withUpdate) {
            massUpdatePools();
        }
        if (block.timestamp < poolStartTime) {
            // chef is sleeping
            if (_lastRewardTime == 0) {
                _lastRewardTime = poolStartTime;
            } else {
                if (_lastRewardTime < poolStartTime) {
                    _lastRewardTime = poolStartTime;
                }
            }
        } else {
            // chef is cooking
            if (_lastRewardTime == 0 || _lastRewardTime < block.timestamp) {
                _lastRewardTime = block.timestamp;
            }
        }
        require(_lastRewardTime <= poolEndTime, "GenesisFarm: add: late"); // MODIFIED (Tomb: no such check)
        bool _isStarted = (_lastRewardTime <= poolStartTime) || (_lastRewardTime <= block.timestamp);
        poolInfo.push(
            PoolInfo({
                token: _token,
                allocPoint: _allocPoint,
                lastRewardTime: _lastRewardTime,
                accRewardPerShare: 0,
                isStarted: _isStarted,
                depositFeeBP: _depositFeeBP
            })
        );
        if (_isStarted) {
            totalAllocPoint = totalAllocPoint + _allocPoint;
        }
    }

    // Update the given pool's xGFANG allocation point. Can only be called by the owner.
    function set(uint256 _pid, uint256 _allocPoint, uint16 _depositFeeBP) public onlyOwner {
        require(_depositFeeBP <= 500, "GenesisFarm: set: invalid deposit fee basis points");
        massUpdatePools();
        PoolInfo storage pool = poolInfo[_pid];
        if (pool.isStarted) {
            totalAllocPoint = totalAllocPoint - pool.allocPoint + _allocPoint;
        }
        pool.allocPoint = _allocPoint;
        pool.depositFeeBP = _depositFeeBP;
    }

    // Return accumulate rewards over the given _from to _to block.
    function getGeneratedReward(uint256 _fromTime, uint256 _toTime) public view returns (uint256) {
        if (_fromTime >= _toTime) return 0;
        if (_toTime >= poolEndTime) {
            if (_fromTime >= poolEndTime) return 0;
            if (_fromTime <= poolStartTime) return (poolEndTime - poolStartTime) * rewardPerSecond;
            return (poolEndTime - _fromTime) * rewardPerSecond;
        } else {
            if (_toTime <= poolStartTime) return 0;
            if (_fromTime <= poolStartTime) return (_toTime - poolStartTime) * rewardPerSecond;
            return (_toTime - _fromTime) * rewardPerSecond;
        }
    }

    // View function to see pending xGFANG on frontend.
    function pendingReward(uint256 _pid, address _user) external view returns (uint256) {
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][_user];
        uint256 accRewardPerShare = pool.accRewardPerShare;
        uint256 tokenSupply = pool.token.balanceOf(address(this));
        if (block.timestamp > pool.lastRewardTime && tokenSupply != 0) {
            uint256 _generatedReward = getGeneratedReward(pool.lastRewardTime, block.timestamp);
            uint256 _reward = _generatedReward * pool.allocPoint / totalAllocPoint;
            accRewardPerShare = accRewardPerShare + _reward * 1e18 / tokenSupply;
        }
        return user.amount * accRewardPerShare / 1e18 - user.rewardDebt;
    }

    // Update reward variables for all pools. Be careful of gas spending!
    function massUpdatePools() public {
        uint256 length = poolInfo.length;
        for (uint256 pid = 0; pid < length; ++pid) {
            updatePool(pid);
        }
    }

    // Update reward variables of the given pool to be up-to-date.
    function updatePool(uint256 _pid) public {
        PoolInfo storage pool = poolInfo[_pid];
        if (block.timestamp <= pool.lastRewardTime) {
            return;
        }
        uint256 tokenSupply = pool.token.balanceOf(address(this));
        if (tokenSupply == 0) {
            pool.lastRewardTime = block.timestamp;
            return;
        }
        if (!pool.isStarted) {
            pool.isStarted = true;
            totalAllocPoint = totalAllocPoint + pool.allocPoint;
        }
        if (totalAllocPoint > 0) {
            uint256 _generatedReward = getGeneratedReward(pool.lastRewardTime, block.timestamp);
            uint256 _reward = _generatedReward * pool.allocPoint / totalAllocPoint;
            pool.accRewardPerShare = pool.accRewardPerShare + _reward * 1e18 / tokenSupply;
        }
        pool.lastRewardTime = block.timestamp;
    }

    // Deposit LP tokens.
    function deposit(uint256 _pid, uint256 _amount) public nonReentrant {
        require(block.timestamp < poolEndTime, "GenesisFarm: deposits closed"); // MODIFIED (Tomb: deposits never close)
        address _sender = msg.sender;
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][_sender];
        updatePool(_pid);
        if (user.amount > 0) {
            uint256 _pending = user.amount * pool.accRewardPerShare / 1e18 - user.rewardDebt;
            if (_pending > 0) {
                _safeRewardTransfer(_sender, _pending);
                emit RewardPaid(_sender, _pending);
            }
        }
        if (_amount > 0) {
            pool.token.safeTransferFrom(_sender, address(this), _amount);
            // MODIFIED (Fee block from SpiritSwap MasterChef, instead of Tomb's fixed 1% fee on shiba)
            if (pool.depositFeeBP > 0) {
                uint256 depositFee = _amount * pool.depositFeeBP / 10000;
                pool.token.safeTransfer(owner(), depositFee);
                user.amount = user.amount + _amount - depositFee;
            } else {
                user.amount = user.amount + _amount;
            }
        }
        user.rewardDebt = user.amount * pool.accRewardPerShare / 1e18;
        emit Deposit(_sender, _pid, _amount);
    }

    // Withdraw LP tokens.
    function withdraw(uint256 _pid, uint256 _amount) public nonReentrant {
        _withdraw(_pid, _amount, true); // MODIFIED (Tomb: the body of _withdraw was inline here)
    }

    // MODIFIED (Tomb: withdraw's body, with _toUser deciding whether the principal leaves the farm)
    function _withdraw(uint256 _pid, uint256 _amount, bool _toUser) internal {
        address _sender = msg.sender;
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][_sender];
        require(user.amount >= _amount, "GenesisFarm: withdraw: not good");
        updatePool(_pid);
        uint256 _pending = user.amount * pool.accRewardPerShare / 1e18 - user.rewardDebt;
        if (_pending > 0) {
            _safeRewardTransfer(_sender, _pending);
            emit RewardPaid(_sender, _pending);
        }
        if (_amount > 0) {
            user.amount = user.amount - _amount;
            if (_toUser) pool.token.safeTransfer(_sender, _amount); // MODIFIED (Tomb: unconditional)
        }
        user.rewardDebt = user.amount * pool.accRewardPerShare / 1e18;
        emit Withdraw(_sender, _pid, _amount);
    }

    // Withdraw without caring about rewards. EMERGENCY ONLY.
    function emergencyWithdraw(uint256 _pid) public nonReentrant {
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][msg.sender];
        uint256 _amount = user.amount;
        user.amount = 0;
        user.rewardDebt = 0;
        pool.token.safeTransfer(msg.sender, _amount);
        emit EmergencyWithdraw(msg.sender, _pid, _amount);
    }

    // Safe xGFANG transfer function, just in case if rounding error causes pool to not have enough xGFANGs.
    function _safeRewardTransfer(address _to, uint256 _amount) internal {
        uint256 _rewardBalance = rewardToken.balanceOf(address(this));
        if (_rewardBalance > 0) {
            if (_amount > _rewardBalance) {
                rewardToken.safeTransfer(_to, _rewardBalance);
            } else {
                rewardToken.safeTransfer(_to, _amount);
            }
        }
    }

    function governanceRecoverUnsupported(IERC20 _token, uint256 amount, address to) external onlyOwner {
        if (block.timestamp < poolEndTime + 90 days) {
            // do not allow to drain core token (xGFANG or lps) if less than 90 days after pool ends
            require(_token != rewardToken, "GenesisFarm: xGFANG");
            uint256 length = poolInfo.length;
            for (uint256 pid = 0; pid < length; ++pid) {
                PoolInfo storage pool = poolInfo[pid];
                require(_token != pool.token, "GenesisFarm: pool.token");
            }
        }
        _token.safeTransfer(to, amount);
    }

    // ************************************************************************************************
    // END OF FORK
    // ************************************************************************************************

    // ************************************************************************************************
    // MERIDIAN MODIFICATIONS
    //
    // Additive: conversion of staked principal into xGFANG through Convertible during CONVERT_WINDOW
    // after poolEndTime, built on the fork's own _withdraw.
    // ************************************************************************************************

    uint256 public constant CONVERT_WINDOW = 24 hours;
    address public convertible;

    event ConvertibleUpdated(address indexed convertible);
    event Convert(address indexed user, uint256 indexed pid, uint256 amount, uint256 xgfangOut);

    modifier onlyConvertWindow() {
        require(convertible != address(0), "GenesisFarm: convertible not set");
        require(
            block.timestamp >= poolEndTime && block.timestamp < poolEndTime + CONVERT_WINDOW,
            "GenesisFarm: convert window closed"
        );
        _;
    }

    /// @notice Sets the Convertible contract.
    function setConvertible(address _convertible) external onlyOwner {
        convertible = _convertible;
        emit ConvertibleUpdated(_convertible);
    }

    /// @notice Converts `_amount` of the caller's staked principal in pool `_pid` into xGFANG at the launch price.
    function convert(uint256 _pid, uint256 _amount) external onlyConvertWindow nonReentrant returns (uint256 pegTokenOut) {
        require(_amount > 0, "GenesisFarm: convert: not good");
        _withdraw(_pid, _amount, false); // Standard withdraw plus keep tokens in farm contract to convert
        IERC20 token = poolInfo[_pid].token;
        token.forceApprove(convertible, _amount);
        pegTokenOut = IConvertible(convertible).convert(address(token), _amount, msg.sender);
        emit Convert(msg.sender, _pid, _amount, pegTokenOut);
    }

    // Frontend helper for claim.
    function harvest(uint256[] calldata _pid) external {
        for (uint256 i = 0; i < _pid.length; ++i) {
            withdraw(_pid[i], 0);
        }
    }
}
"
